// Read API keys and user input from webhook body
const body = $json.body || {};
const BEDROCK_TOKEN = body.bedrock_api_key || '';
const FRAUD_KEY = body.anti_fraud_api_key || '';
const userText = body.text || '';

const systemPrompt = `You are an anti-fraud analysis router. Analyze the user's message and extract:
1. Any URLs (http://, https://, or bare domains like example.com)
2. Any phone numbers (any format: +886..., 09..., 02-xxxx-xxxx, etc.)

Return ONLY valid JSON:
{
  "urls": ["https://example.com"],
  "phones": [{"country": "TW", "number": "+886289667000"}],
  "has_text_content": true,
  "summary": "brief description of what was found"
}

Rules:
- For Taiwan numbers without country code (e.g. 0289667000, 09xx), remove leading 0, prepend +886, set country to "TW"
- For URLs without protocol, prepend https://
- has_text_content: true if the message contains suspicious text worth analyzing beyond URLs/phones
- If nothing is found, return empty arrays
- ONLY return the JSON object, no markdown, no explanation`;

const bedrockBody = {
  modelId: 'us.anthropic.claude-haiku-4-5-20251001-v1:0',
  system: [{ text: systemPrompt }],
  messages: [
    { role: 'user', content: [{ text: userText }] }
  ]
};

let parsed;
try {
  const bedrockResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://bedrock-runtime.us-west-2.amazonaws.com/model/us.anthropic.claude-haiku-4-5-20251001-v1%3A0/converse',
    headers: {
      'Authorization': 'Bearer ' + BEDROCK_TOKEN,
      'Content-Type': 'application/json'
    },
    body: bedrockBody,
    json: true,
    timeout: 30000
  });
  const content = bedrockResp.output.message.content[0].text;
  // Strip markdown fences if present
  let cleanContent = content.trim();
  if (cleanContent.startsWith('```')) {
    cleanContent = cleanContent.split('\n').filter(l => !l.trim().startsWith('```')).join('\n');
  }
  parsed = JSON.parse(cleanContent);
} catch (e) {
  parsed = { urls: [], phones: [], has_text_content: true, summary: 'LLM error: ' + e.message };
}

return [{
  json: {
    urls: parsed.urls || [],
    phones: parsed.phones || [],
    has_text_content: parsed.has_text_content !== false,
    summary: parsed.summary || '',
    original_text: userText,
    image_base64: null,
    anti_fraud_api_key: FRAUD_KEY,
    bedrock_api_key: BEDROCK_TOKEN
  }
}];

const data = $json;
const API_KEY = data.anti_fraud_api_key;
const BASE = 'https://hljaj2f6gf.execute-api.ap-northeast-1.amazonaws.com/prod';

const results = { url_results: [], number_results: [], content_result: null };
const self = this;

// --- URL Check (cache-first strategy) ---
for (let i = 0; i < data.urls.length; i++) {
  const url = data.urls[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    // Try cache first
    let d;
    let usedCache = false;
    try {
      d = await self.helpers.httpRequest({
        method: 'POST',
        url: `${BASE}/url-check-cache`,
        headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
        body: { url },
        json: true
      });
      usedCache = true;
    } catch (cacheErr) {
      // Cache miss (404) or stale (503) — fall back to full check
      await new Promise(r => setTimeout(r, 1100));
      d = await self.helpers.httpRequest({
        method: 'POST',
        url: `${BASE}/url-check`,
        headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
        body: { url },
        json: true
      });
    }
    results.url_results.push({
      url, http_status: 200,
      score: d.score ?? null,
      score_status: d.score_status ?? null,
      domain: d.domain ?? url,
      blacklisted: d.blacklisted ?? null,
      cached: usedCache,
      registration_created: d.whois?.registration_created ?? null,
      registrant_country: d.whois?.registrant?.country ?? null,
      registrar_name: d.whois?.registrar?.name ?? null,
      ssl_valid: d.ssl?.valid ?? null,
      ssl_issuer: d.ssl?.issuer ?? null,
      phishing_count: d.antiphishing?.count ?? 0,
      threat_count: d.dnsblock?.threat?.count ?? 0,
      pageview: d.pageview ?? null,
      redirected_urls: d.redirected_urls ?? []
    });
  } catch (e) {
    results.url_results.push({ url, http_status: e.httpCode || e.status || e.statusCode || 0, error: e.message });
  }
}

// --- Number Check ---
for (let i = 0; i < data.phones.length; i++) {
  const phone = data.phones[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    const d = await self.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/number-check/${phone.country}/${encodeURIComponent(phone.number)}`,
      headers: { 'x-api-key': API_KEY },
      json: true
    });
    results.number_results.push({
      number: phone.number, country: phone.country, http_status: 200,
      name: d.data?.name ?? null,
      region: d.data?.region ?? null,
      business_categories: d.data?.business_categories ?? [],
      spam_category: d.data?.spam_category ?? null
    });
  } catch (e) {
    results.number_results.push({ number: phone.number, country: phone.country, http_status: e.httpCode || e.status || e.statusCode || 0, error: e.message });
  }
}

// --- Build display text ---
const lines = [];
for (const u of results.url_results) {
  if (u.score != null) {
    lines.push(`URL: ${u.domain}`);
    lines.push(`- Score: ${u.score}/100`);
    lines.push(`- Blacklisted: ${u.blacklisted}`);
    lines.push(`- Cached: ${u.cached}`);
    lines.push(`- Registration Created: ${u.registration_created}`);
    lines.push(`- Registrant Country: ${u.registrant_country}`);
    lines.push(`- Registrar Name: ${u.registrar_name}`);
    lines.push(`- SSL Valid: ${u.ssl_valid} (Issuer: ${u.ssl_issuer})`);
    lines.push(`- Phishing Count: ${u.phishing_count}`);
    lines.push(`- Threat Block Count: ${u.threat_count}`);
    lines.push(`- Page Views: ${u.pageview}`);
    lines.push(`- Redirects: ${u.redirected_urls.length > 0 ? u.redirected_urls.join(', ') : 'None'}`);
  } else {
    lines.push(`URL ${u.url}: 查詢失敗 (HTTP ${u.http_status})`);
  }
}
for (const n of results.number_results) {
  lines.push(`Phone: ${n.number}`);
  lines.push(`- Real Name: ${n.name}`);
  lines.push(`- Region: ${n.region}`);
  lines.push(`- Business Categories: ${n.business_categories.join(', ')}`);
  lines.push(`- Spam Category: ${n.spam_category}`);
}
if (lines.length === 0) {
  lines.push('No URL or Phone number found.');
}

return [{
  json: {
    summary: data.summary,
    display_text: lines.join('\n'),
    url_results: results.url_results,
    number_results: results.number_results,
    content_result: null,
    original_text: data.original_text,
    bedrock_api_key: data.bedrock_api_key
  }
}];

// Keyword Check: call our local API to match user text against keyword index
const data = $json;
const PIPELINE_API = 'http://172.19.0.1:5001';

let keywordMatch = { matched_categories: {}, matched_context: {}, match_score: 0, has_match: false };

try {
  keywordMatch = await this.helpers.httpRequest({
    method: 'POST',
    url: `${PIPELINE_API}/keyword-check`,
    headers: { 'Content-Type': 'application/json' },
    body: { text: data.original_text },
    json: true,
    timeout: 15000
  });
} catch (e) {
  keywordMatch.error = 'Keyword check failed: ' + e.message;
}

return [{
  json: {
    ...data,
    keyword_match: keywordMatch
  }
}];

// Conclusion Agent: send all accumulated data to our local API for final judgment
const data = $json;
const PIPELINE_API = 'http://172.19.0.1:5001';

let conclusion = {};
try {
  conclusion = await this.helpers.httpRequest({
    method: 'POST',
    url: `${PIPELINE_API}/conclude`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      user_input: data.original_text,
      keyword_match: data.keyword_match,
      url_results: data.url_results,
      number_results: data.number_results
    },
    json: true,
    timeout: 60000
  });
} catch (e) {
  conclusion = { error: 'Conclusion agent failed: ' + e.message };
}

// Build final display text
const lines = [];
lines.push('=== 麥騙 FakeOff 防詐分析報告 ===');
lines.push('');

// External API results
if (data.display_text && data.display_text !== 'No URL or Phone number found.') {
  lines.push('【外部查詢結果】');
  lines.push(data.display_text);
  lines.push('');
}

// Keyword match
const km = data.keyword_match;
if (km && km.has_match) {
  const cats = Object.keys(km.matched_categories || {}).join(', ');
  lines.push(`【關鍵字命中】類別: ${cats} (風險分數: ${km.match_score})`);
  lines.push('');
}

// AI Conclusion
lines.push('【AI 詐騙判斷】');
if (conclusion.is_scam !== undefined) {
  const scamLabel = conclusion.is_scam === true ? '高度可疑詐騙' :
                    conclusion.is_scam === false ? '看起來安全' : '無法確定';
  lines.push(`判定: ${scamLabel}`);
  lines.push(`信心度: ${Math.round((conclusion.confidence || 0) * 100)}%`);
  if (conclusion.scam_type) lines.push(`詐騙類型: ${conclusion.scam_type}`);
  lines.push(`分析: ${conclusion.reasoning || ''}`);
  if (conclusion.red_flags && conclusion.red_flags.length > 0) {
    lines.push(`可疑特徵: ${conclusion.red_flags.join('、')}`);
  }
  if (conclusion.matched_news_event) {
    lines.push(`相關新聞: ${conclusion.matched_news_event}`);
  }
  if (conclusion.matched_tactic) {
    lines.push(`吻合手法: ${conclusion.matched_tactic}`);
  }
  lines.push('');
  lines.push(`建議: ${conclusion.advice || ''}`);
} else if (conclusion.error) {
  lines.push(`分析失敗: ${conclusion.error}`);
} else {
  lines.push(JSON.stringify(conclusion, null, 2));
}

return [{
  json: {
    display_text: lines.join('\n'),
    conclusion: conclusion,
    keyword_match: data.keyword_match,
    url_results: data.url_results,
    number_results: data.number_results,
    original_text: data.original_text
  }
}];
